const DIRS = [[-1, 0], [1, 0], [0, -1], [0, 1]];

function orangesRotting(grid) {
  const rows = grid.length, cols = grid[0].length;
  let minutes = 0;
  while (true) {
    const toRot = [];                     // fresh oranges next to a rotten one, this minute
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (grid[r][c] !== 1) continue;
        for (const [dr, dc] of DIRS) {
          const nr = r + dr, nc = c + dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === 2) {
            toRot.push([r, c]);
            break;
          }
        }
      }
    }
    if (toRot.length === 0) break;        // nothing changed: the spread has stopped
    for (const [r, c] of toRot) grid[r][c] = 2;   // rot them together, after the scan
    minutes++;
  }
  for (const row of grid) if (row.includes(1)) return -1;   // a fresh orange nobody can reach
  return minutes;
}

